			i++
			continue
		}
		if strings.HasPrefix(a, "--") {
			// long flag
			eqIdx := strings.Index(a, "=")
			var name, val string
			hasEq := false
			if eqIdx != -1 {
				name = a[2:eqIdx]
				val = a[eqIdx+1:]
				hasEq = true
			} else {
				name = a[2:]
			}
			if name == "" {
				// "--" handled above, "--=..."? treat as unknown?
				errMsg = fmt.Sprintf("unknown flag: %s", a)
				return
			}
			def, ok := longToDef[name]
			if !ok {
				// check for help/version special? They are defined as flags, so ok
				errMsg = fmt.Sprintf("unknown flag: --%s", name)
				return
			}
			if def.Type == "bool" {
				if hasEq {
					// parse bool value
					b, err := parseBool(val)
					if err != nil {
						errMsg = fmt.Sprintf("invalid argument %q for \"--%s\" flag: %v", val, name, err)
						return
					}
					parsed.Bools[def.Long] = b
					if def.Long == "help" {
						parsed.Help = b // actually help true? If --help=false, then Help false?
						// In cobra, --help=false means don't show help. We'll handle: Help = b
					}
				} else {
					parsed.Bools[def.Long] = true
					if def.Long == "help" {
						parsed.Help = true
					}
				}
				i++
				continue
			} else {
				// needs value
				var v string
				if hasEq {
					v = val
				} else {
					if i+1 >= len(args) {
						errMsg = fmt.Sprintf("flag needs an argument: --%s", name)
						return
					}
					v = args[i+1]
					i++ // consume value
				}
				if def.Type == "string" {
					parsed.Values[def.Long] = v
				} else if def.Type == "duration" {
					d, err := time.ParseDuration(v)
					if err != nil {
						// need to format like pflag: invalid argument "xxx" for "-w, --wait" flag: ...
						// For wait, short is w, long wait. Format: "-w, --wait"
						// For other durations? Only wait uses duration. Good.
						// Construct flag display: if short != "", "-s, --long" else "--long"
						var disp string
						if def.Short != "" {
							disp = fmt.Sprintf("-%s, --%s", def.Short, def.Long)
						} else {
							disp = fmt.Sprintf("--%s", def.Long)
						}
						errMsg = fmt.Sprintf("invalid argument %q for %q flag: %v", v, disp, err)
						return
					}
					parsed.Durations[def.Long] = d
				} else if def.Type == "strings" {
					// split by comma, no trimming, accumulate
					parts := strings.Split(v, ",")
					parsed.StringSlices[def.Long] = append(parsed.StringSlices[def.Long], parts...)
				}
				i++
				continue
			}
		} else if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short flags, possibly combined
			// Handle "-h", "-v", "-q", "-o", "-c", "-f", "-w", "-d", etc.
			// Need to handle "-ojson", "-o=json", "-o json", "-cprofile", etc., and "-qh" (combined bools)
			chars := a[1:]
			// Check for "=" in chars? e.g., "-o=json" => short o, value "=json"? Actually pflag: "-o=json" => short o, value "json" (after =)
			// Similarly "-q=false" => short q, value "false" after =
			// Handle first char
			pos := 0
			for pos < len(chars) {
				ch := string(chars[pos])
				def, ok := shortToDef[ch]
				if !ok {
					errMsg = fmt.Sprintf("unknown shorthand flag: '%s' in -%s", ch, chars)
					return
				}
				if def.Type == "bool" {
					// check if rest starts with "="? e.g., "-q=false" => chars "q=false", pos0 q, rest "=false"
					rest := chars[pos+1:]
					if strings.HasPrefix(rest, "=") {
						val := rest[1:]
						b, err := parseBool(val)
						if err != nil {
							// For bool short, error format? Likely similar: invalid argument "xxx" for "-q, --quiet" flag: ...
							var disp string
							if def.Long != "" {
								disp = fmt.Sprintf("-%s, --%s", def.Short, def.Long)
							} else {
								disp = fmt.Sprintf("-%s", def.Short)
							}
							errMsg = fmt.Sprintf("invalid argument %q for %q flag: %v", val, disp, err)
							return
						}
						parsed.Bools[def.Long] = b
						if def.Long == "help" {
							parsed.Help = b
						}
						// consumed all
						break
					} else {
						// bool true, continue to next char (for combined like -qh)
						parsed.Bools[def.Long] = true
						if def.Long == "help" {
							parsed.Help = true
						}
						pos++
						continue
					}
				} else {
					// needs value: if there are remaining chars after this short, they are value (with optional =?)
					rest := chars[pos+1:]
					var v string
					if rest != "" {
						if strings.HasPrefix(rest, "=") {
							v = rest[1:]
						} else {
							v = rest
						}
						// consumed all
					} else {
						// next arg as value
						if i+1 >= len(args) {
							errMsg = fmt.Sprintf("flag needs an argument: '-%s' in -%s", ch, chars)
							// Actually pflag message for short missing? Let's check: what is message for "-o" without value?
							// We haven't tested "-o" without value. Likely "flag needs an argument: 'o' in -o" or similar?
							// Need to test. For now, use this format, will adjust after testing.
							return
						}
						v = args[i+1]
						i++ // consume
					}
					if def.Type == "string" {
						parsed.Values[def.Long] = v
					} else if def.Type == "duration" {
						d, err := time.ParseDuration(v)
						if err != nil {
							var disp string
							if def.Long != "" {
								disp = fmt.Sprintf("-%s, --%s", def.Short, def.Long)
							} else {
								disp = fmt.Sprintf("-%s", def.Short)
							}
							errMsg = fmt.Sprintf("invalid argument %q for %q flag: %v", v, disp, err)
							return
						}
						parsed.Durations[def.Long] = d
					} else if def.Type == "strings" {
						parts := strings.Split(v, ",")
						parsed.StringSlices[def.Long] = append(parsed.StringSlices[def.Long], parts...)
					}
					// for non-bool, consumed rest, break inner loop
					break
				}
			}
			i++
			continue
		} else {
			// positional
			positional = append(positional, a)
			i++
			continue
		}
	}
	return
}

func parseBool(s string) (bool, error) {
	switch strings.ToLower(s) {
	case "1", "t", "true":
		return true, nil
	case "0", "f", "false":
		return false, nil
	default:
		return false, fmt.Errorf("strconv.ParseBool: parsing %q: invalid syntax", s)
	}
}

// ---------- Help texts ----------
func getBackupHelp() string {
	cwd, err := os.Getwd()
	if err != nil {
		cwd = "/workspace"
	}
	return fmt.Sprintf(helpBackupTemplate, cwd)
}

// Unknown help topic output (to stderr)
func unknownHelpTopic(args []string) string {
	// args are the invalid help path? For "help unknown" => ["unknown"], for "help foo bar" => ["foo","bar"]
	// Format: Unknown help topic [`unknown`] or [`foo` `bar`]
	var quoted []string
	for _, a := range args {
		quoted = append(quoted, "`"+a+"`")
	}
	inner := strings.Join(quoted, " ")
	// Build output: "Unknown help topic [inner]\n" + root help from Usage onwards WITHOUT -h/-v?
	// Root help from Usage, but Flags without -h/-v
	// Let's construct manually to match observed:
	// Observed Unknown stderr starts with "Unknown help topic [...] \nUsage:\n  hostctl [command]\n\nAvailable Commands:...\n\nFlags:\n  -c...\n      --host-file...\n      --no-color...\n  -o...\n  -q...\n      --raw...\n\nUse ...\n"
	// Note: no -h, no -v, no description, no leading \n
	s := fmt.Sprintf("Unknown help topic [%s]\n", inner)
	s += "Usage:\n"
	s += "  hostctl [command]\n"
	s += "\n"
	s += "Available Commands:\n"
	s += "  add         Add content to a profile in your hosts file.\n"
	s += "  backup      Creates a backup copy of your hosts file\n"
	s += "  disable     Disable a profile from your hosts file.\n"
	s += "  enable      Enable a profile on your hosts file.\n"
	s += "  help        Help about any command\n"
	s += "  list        Shows a detailed list of profiles on your hosts file.\n"
	s += "  remove      Remove a profile from your hosts file.\n"
	s += "  replace     Replace content to a profile in your hosts file.\n"
	s += "  restore     Restore hosts file content from a backup file.\n"
	s += "  status      Shows a list of profile names and statuses on your hosts file.\n"
	s += "  sync        Sync some system IPs with a profile.\n"
	s += "  toggle      Change status of a profile on your hosts file.\n"
	s += "\n"
	s += "Flags:\n"
	s += "  -c, --column strings     Column names to show on lists. comma separated\n"
	s += "      --host-file string   Hosts file path (default \"/etc/hosts\")\n"
	s += "      --no-color           force colorless output\n"
	s += "  -o, --out string         Output type (table|raw|markdown|json) (default \"table\")\n"
	s += "  -q, --quiet              Run command without output\n"
	s += "      --raw                Output without borders (same as -o raw)\n"
	s += "\n"
	s += "Use \"hostctl [command] --help\" for more information about a command.\n"
	return s
}

