func leftPadRaw(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func renderJSON(groups [][]HostEntry, forStatus bool) string {
	// Flatten groups in order (for list, default first, then profiles in order; for status, profiles in order)
	var flat []HostEntry
	for _, g := range groups {
		flat = append(flat, g...)
	}
	if len(flat) == 0 {
		return "null\n"
	}
	// For status, IP/Host empty, but still include? Yes, as observed: status json has IP:"",Host:"". Good.
	// JSON field order: Profile,Status,IP,Host (as observed). Use struct with json tags in order.
	type jEntry struct {
		Profile string `json:"Profile"`
		Status string `json:"Status"`
		IP string `json:"IP"`
		Host string `json:"Host"`
	}
	var jlist []jEntry
	for _, e := range flat {
		jlist = append(jlist, jEntry{Profile: e.Profile, Status: e.Status, IP: e.IP, Host: e.Host})
	}
	b, _ := json.Marshal(jlist)
	return string(b) + "\n"
}

