func doWait(d time.Duration, revert func()) {
	if d < 0 {
		return
	}
	if d == 0 {
		// Wait until interrupt (SIGINT/SIGTERM)
		c := make(chan os.Signal, 1)
		signal.Notify(c, os.Interrupt, syscall.SIGTERM)
		<-c
		signal.Stop(c)
		revert()
		return
	}
	// Wait for duration or interrupt
	c := make(chan os.Signal, 1)
	signal.Notify(c, os.Interrupt, syscall.SIGTERM)
	select {
	case <-time.After(d):
		signal.Stop(c)
		revert()
	case <-c:
		signal.Stop(c)
		revert()
	}
}

